import re

def parse_duration(text: str) -> int:
    text = text.strip()
    if not text:
        raise ValueError('empty string')
    pattern = r'^\s*(?:(\d+)d)?\s*(?:(\d+)h)?\s*(?:(\d+)m)?\s*(?:(\d+)s)?\s*$'
    m = re.match(pattern, text)
    if not m:
        raise ValueError('invalid format')
    d, h, m_val, s = m.groups()
    total = 0
    if d:
        total += int(d) * 86400
    if h:
        total += int(h) * 3600
    if m_val:
        total += int(m_val) * 60
    if s:
        total += int(s)
    if total == 0 and not any([d, h, m_val, s]):
        raise ValueError('no units')
    return total

import re

def parse_duration(text: str) -> int:
    text = text.strip()
    if not text:
        raise ValueError('Empty duration')
    pattern = r'^(?:(\d+)d)?\s*(?:(\d+)h)?\s*(?:(\d+)m)?\s*(?:(\d+)s)?$'
    match = re.match(pattern, text)
    if not match:
        raise ValueError('Invalid duration format')
    days, hours, minutes, seconds = match.groups()
    total = 0
    if days:
        total += int(days) * 86400
    if hours:
        total += int(hours) * 3600
    if minutes:
        total += int(minutes) * 60
    if seconds:
        total += int(seconds)
    if total == 0 and not any([days, hours, minutes, seconds]):
        raise ValueError('No duration specified')
    return total

import re

def parse_duration(text: str) -> int:
    text = text.strip()
    if not text:
        raise ValueError('Empty duration')

    pattern = r'^(?:(\d+)d)?\s*(?:(\d+)h)?\s*(?:(\d+)m)?\s*(?:(\d+)s)?\s*$'
    match = re.match(pattern, text)
    if not match:
        raise ValueError('Invalid duration format')

    days, hours, minutes, seconds = match.groups()
    total = 0
    if days:
        total += int(days) * 86400
    if hours:
        total += int(hours) * 3600
    if minutes:
        total += int(minutes) * 60
    if seconds:
        total += int(seconds)

    if total == 0 and not any([days, hours, minutes, seconds]):
        raise ValueError('Invalid duration')

    return total

def chunk(items: list, size: int) -> list[list]:
    if size <= 0:
        raise ValueError("size must be positive")
    return [items[i:i+size] for i in range(0, len(items), size)]

